require_once __DIR__.'/../config/config.php';$user=require_employee_user();$pdo=db();$employee=employee_owner($pdo,$user);$q=$pdo->prepare('SELECT * FROM profile_change_requests WHERE id=? AND employee_id=?');$q->execute([(int)($_GET['id']??0),$employee['id']]);$request=$q->fetch();if(!$request){http_response_code(404);exit('Request not found.');}$pageTitle='Request details';require __DIR__.'/../includes/header.php';?><div class="mb-7"><a href="requests.php" class="text-sm font-bold text-teal-700">← My requests</a><h1 class="font-display text-3xl font-bold mt-2">Request #<?=e($request['id'])?></h1></div><section class="bg-white border rounded-xl p-6 max-w-2xl space-y-5 text-sm"><?php foreach(['Request type'=>'request_type','Field'=>'requested_field','Current value'=>'old_value','Requested value'=>'requested_value','Reason'=>'reason','Supporting information'=>'supporting_information','Status'=>'status','Submitted'=>'created_at','HR remarks'=>'review_reason','Reviewed'=>'reviewed_at'] as $label=>$field):?><div><p class="text-xs text-slate-400"><?=e($label)?></p><p class="font-semibold mt-1 whitespace-pre-wrap"><?=e($request[$field]??'—')?></p></div><?php endforeach;?></section><?php require __DIR__.'/../includes/footer.php';